sys_variable_value.value:
(function execute(inputs, outputs) {
    var response = '';
    var enc_qry = 'company.name='+inputs.company+'^department.name='+inputs.department+'^port.port='+inputs.port+'^active=true^onboarding_item_type=app';
    var onb_mtrx = new GlideRecord('x_snc_cpa_onboar_0_onboarding_matrix');
    onb_mtrx.addEncodedQuery(enc_qry);
    onb_mtrx.query();
    var app_data = [];
    while(onb_mtrx.next()) {
        var onb = {};
        onb.item = onb_mtrx.getDisplayValue('onboarding_item');
        onb.approval_grp = onb_mtrx.getDisplayValue('approval_group');
        onb.approval_req = onb_mtrx.getDisplayValue('approval_required');
        onb.is_default = onb_mtrx.getDisplayValue('default_app_hw');
        onb.fulfil_grp1 = onb_mtrx.getDisplayValue('fulfilment_group_1');
        onb.fulfil_grp2 = onb_mtrx.getDisplayValue('fulfilment_group_2');
        app_data.push(onb);
    }
    response = JSON.stringify(app_data);
    outputs.app_data = response;

})(inputs, outputs);

